cur=load(); b=cur['board']
# connected components of green
pts={(x,y) for y,row in enumerate(b) for x,v in enumerate(row) if v==14}
comps=[]
while pts:
 seed=pts.pop(); stack=[seed]; comp=[seed]
 while stack:
  x,y=stack.pop()
  for p in [(x+1,y),(x-1,y),(x,y+1),(x,y-1)]:
   if p in pts: pts.remove(p); stack.append(p); comp.append(p)
 comps.append(comp)
centers=[(sum(x for x,y in c)//len(c),sum(y for x,y in c)//len(c),len(c)) for c in comps]
print(sorted(centers,key=lambda z:(z[1],z[0])))
